# --------------------------------------------------
# DATA CLASSES
# --------------------------------------------------

@dataclass
class RainRecord:
    date_str: str
    rain_inches: float
    category: str = "Normal"


@dataclass
class AppState:
    location: str = "Newark, Delaware"
    start_date: str = FIRST_DATE
    end_date: str = LATEST_DATE
    active_screen: str = "input"
    rain_records: list[RainRecord] = field(default_factory=list)
    is_downloading: bool = False
    message: str = ""
    heavy_rain_threshold: float = 0.79
    analysis_count: int = 0


# --------------------------------------------------
# RAINFALL CATEGORIES
# --------------------------------------------------

def rainfall_category(amount: float) -> str:
    if amount >= 0.79:
        return "Heavy rain"
    elif amount == 0:
        return "Dry"
    elif amount < 0.10:
        return "Light drizzle"
    else:
        return "Rain"


# --------------------------------------------------
# LOCAL HISTORICAL DATA
# --------------------------------------------------


# --------------------------------------------------

def load_rainfall_data(start_date: str,
                       end_date: str) -> list[RainRecord]:
    """Read the local CSV, or use bundled daily values if it is unavailable.

    The online course runner may not copy extra CSV files into the program's
    virtual folder. The embedded comma-separated amounts are a fallback for
    that case; their dates are consecutive days beginning at FIRST_DATE.
    """
    records = []

    if os.path.exists(DATA_FILE):
        with open(DATA_FILE, "r", newline="", encoding="utf-8") as file:
            reader = csv.DictReader(file)
            for row in reader:
                if start_date <= row["date"] <= end_date:
                    records.append(
                        RainRecord(
                            row["date"],
                            float(row["rainfall_inches"]),
                            row["category"]
                        )
                    )
    else:
        first_day = date.fromisoformat(FIRST_DATE)
        for index, value in enumerate(RAIN_DATA_VALUES.split(",")):
            record_date = (first_day + timedelta(days=index)).isoformat()
            if start_date <= record_date <= end_date:
                amount = float(value)
                records.append(
                    RainRecord(record_date, amount, rainfall_category(amount))
                )

    return records

# --------------------------------------------------
# DATA CALCULATIONS
# --------------------------------------------------

def filtered_records(state: AppState) -> list[RainRecord]:
    selected = []

    for record in state.rain_records:
        if (state.start_date <= record.date_str
                <= state.end_date):
            selected.append(record)

    return selected


def total_rain(records: list[RainRecord]) -> float:
    total = 0.0

    for record in records:
        total += record.rain_inches

    return total


def monthly_totals(records: list[RainRecord]) -> dict:
    totals = {}

    for record in records:
        month = record.date_str[:7]

        if month not in totals:
            totals[month] = 0.0

        totals[month] += record.rain_inches

    return totals


# --------------------------------------------------
# BEST-FIT LINE CALCULATION
# --------------------------------------------------

def calculate_best_fit(values: list[float]):
    """Calculate ordinary least-squares slope and intercept.

    x is the month index (0, 1, 2, ...) and y is that month's rainfall.
    The slope is sum((x-x_mean)*(y-y_mean)) / sum((x-x_mean)**2);
    the intercept is y_mean - slope*x_mean. These values describe the
    straight line that minimizes squared vertical errors. With fewer than
    two months, a trend cannot be estimated, so return a flat line.
    """

    if len(values) < 2:
        return 0.0, values[0] if values else 0.0

    x_values = list(range(len(values)))

    x_mean = sum(x_values) / len(x_values)
    y_mean = sum(values) / len(values)

    numerator = 0.0
    denominator = 0.0

    for x, y in zip(x_values, values):
        numerator += (x - x_mean) * (y - y_mean)
        denominator += (x - x_mean) ** 2

    if denominator == 0:
        return 0.0, y_mean

    slope = numerator / denominator
    intercept = y_mean - slope * x_mean

    return slope, intercept


def trend_description(slope: float) -> str:
    if slope > 0.001:
        return "Rainfall is showing an increasing trend."

    elif slope < -0.001:
        return "Rainfall is showing a decreasing trend."

    else:
        return "Rainfall is relatively stable over this period."


# --------------------------------------------------
# CSV EXPORT
# --------------------------------------------------

def make_csv(records: list[RainRecord]) -> str:
    csv_text = "City,State,Date,Rainfall (inches),Condition\n"

    for record in records:
        csv_text += (
            CITY + ","
            + STATE_NAME + ","
            + record.date_str + ","
            + str(record.rain_inches) + ","
            + record.category + "\n"
        )

    return csv_text


# --------------------------------------------------
# NAVIGATION
# --------------------------------------------------

def navigation(state: AppState) -> list:
    return [
        Button("Daily Dashboard", "view_main_dashboard"),
        Button("Monthly Breakdown", "view_monthly_breakdown"),
        Button("Extreme Weather", "view_extreme_weather"),
        Button("Export Data", "view_export_page"),
        Button("Change Search", "home_input_page"),
        HorizontalRule()
    ]


# --------------------------------------------------
# PAGE 1: HOME / INPUT
# --------------------------------------------------

@route
def index(state: AppState) -> Page:
    return home_input_page(state)


@route
def home_input_page(state: AppState) -> Page:
    state.active_screen = "input"

    return Page(state, [
        Header("Newark, Delaware Rainfall Analyzer"),

        "Explore historical rainfall patterns from 2010 to the present.",

        HorizontalRule(),

        Header("Choose your analysis period", 2),

        state.message if state.message else "",

        "Location:",
        "Newark, Delaware (fixed location)",

        "Start date (YYYY-MM-DD):",
        TextBox("start_date", state.start_date),

        "End date (YYYY-MM-DD):",
        TextBox("end_date", state.end_date),

        "Heavy rainfall threshold (inches):",
        TextBox(
            "heavy_rain_threshold",
            str(state.heavy_rain_threshold)
        ),

        Button("Analyze Rainfall", "process_rain_analysis"),

        HorizontalRule(),

        Header("Project Features", 2),

        BulletedList([
            "Historical rainfall data beginning in 2010",
            "Daily rainfall dashboard",
            "Monthly rainfall comparisons",
            "Best-fit rainfall trend line",
            "Heavy rainfall and dry spell analysis",
            "Downloadable CSV data"
        ]),

        HorizontalRule(),

        "Data source: Open-Meteo Historical Weather API.",
        "Rainfall values are gridded historical estimates, "
        "not direct measurements from a local rain gauge."
    ])


# --------------------------------------------------
# PROCESS FORM
# --------------------------------------------------

@route
def process_rain_analysis(state: AppState,
                          start_date: str,
                          end_date: str,
                          heavy_rain_threshold: str) -> Page:

    # Validate the dates.
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
        threshold = float(heavy_rain_threshold)

    except ValueError:
        state.message = (
            "Please enter valid dates and a valid rainfall threshold."
        )
        return home_input_page(state)

    if start.isoformat() != start_date or end.isoformat() != end_date:
        state.message = "Please use YYYY-MM-DD date format."
        return home_input_page(state)

    if start_date < FIRST_DATE:
        state.message = "The earliest available date is January 1, 2010."
        return home_input_page(state)

    if end_date > LATEST_DATE:
        state.message = (
            "Please choose an end date at least seven days before today."
        )
        return home_input_page(state)

    if start_date > end_date:
        state.message = "The start date must be before the end date."
        return home_input_page(state)

    if threshold <= 0:
        state.message = "The rainfall threshold must be greater than zero."
        return home_input_page(state)

    state.start_date = start_date
    state.end_date = end_date
    state.heavy_rain_threshold = threshold
    state.location = "Newark, Delaware"
    state.is_downloading = True

    try:
        # Use the bundled/local archive; online runners cannot fetch APIs.
        state.rain_records = load_rainfall_data(
            start_date,
            end_date
        )

        state.is_downloading = False

    except Exception as error:
        state.is_downloading = False
        state.message = (
            "Could not read rainfall data. Check that the bundled dataset is "
            "available. Details: " + str(error)
        )
        return home_input_page(state)

    if len(state.rain_records) == 0:
        state.message = "No rainfall records were found for that period."
        return home_input_page(state)

    state.analysis_count += 1
    state.message = ""

    return view_main_dashboard(state)


# --------------------------------------------------
# PAGE 2: DAILY DASHBOARD
# --------------------------------------------------

@route
def view_main_dashboard(state: AppState) -> Page:
    state.active_screen = "dashboard"

    records = filtered_records(state)

    if len(records) == 0:
        return home_input_page(state)

    total = total_rain(records)

    rainiest = records[0]
    rainy_days = 0

    for record in records:
        if record.rain_inches > rainiest.rain_inches:
            rainiest = record

        if record.rain_inches > 0:
            rainy_days += 1

    # Calculate monthly best-fit line.
    totals = monthly_totals(records)
    months = sorted(totals)
    amounts = [totals[month] for month in months]

    slope, intercept = calculate_best_fit(amounts)

    trend_lines = []

    for index, month in enumerate(months):
        predicted = slope * index + intercept

        trend_lines.append(
            month + " | Actual: "
            + str(round(amounts[index], 2))
            + " in | Trend: "
            + str(round(max(0, predicted), 2))
            + " in"
        )

    content = [
        Header("Newark Rainfall Dashboard"),

        "Location: Newark, Delaware",

        "Period: " + state.start_date + " to " + state.end_date,

        "Total rainfall: " + str(round(total, 2)) + " inches",

        "Rainiest day: " + rainiest.date_str
        + " (" + str(rainiest.rain_inches) + " inches)",

        "Rainy days: " + str(rainy_days)
        + " out of " + str(len(records)),

        "Analyses completed: " + str(state.analysis_count),

        HorizontalRule()
    ]

    content.extend(navigation(state))

    content.extend([
        Header("Monthly Rainfall Trend", 2),

        trend_description(slope),

        "Best-fit line slope: "
        + str(round(slope, 4))
        + " inches per month.",

        "The trend values below are calculated using linear regression.",

        BulletedList(trend_lines),

        HorizontalRule(),

        Header("Daily Rainfall Records", 2),

        "The daily data is available in the CSV export."
    ])

    return Page(state, content)


# --------------------------------------------------
# PAGE 3: MONTHLY BREAKDOWN
# --------------------------------------------------

@route
def view_monthly_breakdown(state: AppState) -> Page:
    state.active_screen = "monthly"

    records = filtered_records(state)
    totals = monthly_totals(records)

    month_lines = []

    for month in sorted(totals):
        amount = totals[month]

        bar = "█" * int(amount * 8)

        month_lines.append(
            month + "  "
            + bar + "  "
            + str(round(amount, 2))
            + " inches"
        )

    return Page(state, [
        Header("Monthly Rainfall Breakdown"),

        "Location: Newark, Delaware",

        "Selected period: " + state.start_date
        + " to " + state.end_date,

        HorizontalRule()

    ] + navigation(state) + [
        Header("Rainfall by Month", 2),

        BulletedList(month_lines),

        HorizontalRule(),

        Header("Season Guide", 2),

        "Winter: December, January, February",

        "Spring: March, April, May",

        "Summer: June, July, August",

        "Fall: September, October, November"
    ])


# --------------------------------------------------
# PAGE 4: EXTREME WEATHER
# --------------------------------------------------

@route
def view_extreme_weather(state: AppState) -> Page:
    state.active_screen = "extreme"

    records = filtered_records(state)

    heavy_rain = []
    dry_spells = []
    current_dry_spell = []

    for record in records:

        if record.rain_inches >= state.heavy_rain_threshold:
            heavy_rain.append(
                record.date_str + " — "
                + str(record.rain_inches) + " inches"
            )

        if record.rain_inches == 0:
            current_dry_spell.append(record.date_str)

        else:
            if len(current_dry_spell) >= 2:
                dry_spells.append(
                    current_dry_spell[0]
                    + " through "
                    + current_dry_spell[-1]
                    + " ("
                    + str(len(current_dry_spell))
                    + " days)"
                )

            current_dry_spell = []

    if len(current_dry_spell) >= 2:
        dry_spells.append(
            current_dry_spell[0]
            + " through "
            + current_dry_spell[-1]
            + " ("
            + str(len(current_dry_spell))
            + " days)"
        )

    if len(heavy_rain) == 0:
        heavy_display = "No heavy rainfall days found."

    else:
        heavy_display = BulletedList(heavy_rain)

    if len(dry_spells) == 0:
        dry_display = "No dry spells of two or more days found."

    else:
        dry_display = BulletedList(dry_spells)

    return Page(state, [
        Header("Extreme Weather Analysis"),

        "Location: Newark, Delaware",

        "Selected period: " + state.start_date
        + " to " + state.end_date,

        HorizontalRule()

    ] + navigation(state) + [
        Header("Heavy Rainfall Days", 2),

        "Your heavy-rain threshold: "
        + str(state.heavy_rain_threshold)
        + " inches.",

        heavy_display,

        HorizontalRule(),

        Header("Consecutive Dry Spells", 2),

        "A dry spell is two or more consecutive days with no recorded rain.",

        dry_display,

        HorizontalRule(),

        "These results are educational indicators, not official "
        "flood or drought warnings."
    ])


# --------------------------------------------------
# PAGE 5: EXPORT DATA
# --------------------------------------------------

@route
def view_export_page(state: AppState) -> Page:
    state.active_screen = "export"

    records = filtered_records(state)

    rows = [
        ["Date", "Rainfall (inches)", "Condition"]
    ]

    for record in records:
        rows.append([
            record.date_str,
            str(record.rain_inches),
            record.category
        ])

    csv_contents = make_csv(records)

    return Page(state, [
        Header("Rainfall Data Export"),

        "Location: Newark, Delaware",

        "Selected period: " + state.start_date
        + " to " + state.end_date,

        HorizontalRule()

    ] + navigation(state) + [
        Header("Download Your CSV", 2),

        Download(
            "Download Rainfall CSV",
            "newark_rainfall_export.csv",
            csv_contents,
            content_type="text/csv"
        ),

        HorizontalRule(),

        Header("Rainfall Records", 2),

        Table(rows),

        "Records shown: " + str(len(records)),

        Button("Back to Dashboard", "view_main_dashboard")
    ])


# --------------------------------------------------
# EXTRA DOWNLOAD ROUTE
# --------------------------------------------------

@route
def download_rain_data(state: AppState) -> Page:
    state.is_downloading = True
    state.is_downloading = False

    return view_export_page(state)


